import type { D1AuthoredBank } from '../corpus'

export const LEMBAH_AWAN_D_R4: D1AuthoredBank = {
  universeId: 'lembah-awan',
  rubricId: 'D-R4',
  STRONG: [
    { chapters: [
      { chapterNumber: 6, title: 'Kartu Jatah Dibagikan', paragraphs: ['Kartu jatah air dibagikan di balai desa pada awal musim tanam dan Vina menerima miliknya bersama penanam lereng atas. Petugas menerangkan bahwa angka pada kartu berlaku sampai panen. Vina menyimpan kartu itu di antara lembar buku benih. Malam itu kartu-kartu penanam lain sudah dibawa pulang, sementara kartu Vina tetap tertutup di dalam buku benih.'] },
      { chapterNumber: 14, title: 'Kartu Terlipat di Meja', paragraphs: ['Vina meletakkan kartu jatah air di meja Mandor Bagas dan menunjukkan angka yang dipotong dengan tinta biru. Bagas menepisnya, berkata petak lereng atas selalu terlalu banyak meminta. Di halaman kantor, dua kru saluran memandangi Vina sampai ia melipat kartu itu kembali. Ia pulang dengan malu karena tidak mampu menjawab satu kalimat pun.'] },
      { chapterNumber: 15, title: 'Noda Tinta di Arsip', paragraphs: ['Alih-alih kembali ke kantor, Vina meminta Bu Ningsih membuka lemari arsip sekolah. Di dalam buku kehadiran lama, ia menemukan nama penanam yang pernah menerima jam lebih panjang pada tanggal yang sama. Ia menyalin tiga halaman di meja kelas dan merasa marah, bukan malu, karena pemotongan itu ternyata bukan kesalahannya sendiri.'] },
      { chapterNumber: 16, title: 'Tiga Salinan untuk Warga', paragraphs: ['Vina tidak mendatangi Bagas seorang diri lagi. Ia membagikan salinan arsip kepada tiga penanam sebelum pasar buka dan meminta mereka membaca angka masing-masing. Ketika satu orang menangis melihat namanya, Vina duduk di sampingnya tanpa menyembunyikan kertas. Rasa takutnya berubah menjadi kewajiban kepada orang lain yang kini mengetahui hal sama.'] },
      { chapterNumber: 32, title: 'Papan Jadwal Dihadapi Bersama', paragraphs: ['Delapan belas hari kemudian, papan jadwal kembali dipaku Bagas di gerbang. Vina datang bersama enam pemegang kartu, membawa salinan berbeda dan meminta setiap orang menunjuk namanya sendiri. Bagas tidak lagi berhadapan dengan satu gadis yang gugup, melainkan dengan deret bukti dan suara. Ia menurunkan palunya, sementara Vina menahan napas tanpa ingin lari.'] },
      { chapterNumber: 41, title: 'Arsip Sekolah Diminta Resmi', paragraphs: ['Vina meminta izin tertulis kepada kepala sekolah agar salinan buku kehadiran lama dapat dipakai sebagai keterangan. Izin itu diberikan dengan syarat nama murid ditutup. Ia menyalin ulang seluruh halaman dengan aturan tersebut di ruang guru. Surat izin kepala sekolah diselipkan sebagai halaman depan, lengkap dengan tanggal, tanda tangan, dan cap sekolah.'] },
      { chapterNumber: 42, title: 'Enam Kartu Difoto Copy', paragraphs: ['Keenam pemegang kartu menyerahkan kartu mereka untuk digandakan di kios kecamatan. Vina membawa pulang dua puluh empat lembar salinan dan membagi setengahnya kepada pemiliknya. Setengah lainnya ia simpan pada rumah yang berbeda-beda. Satu bundel masuk lemari sekolah, satu dibawa Danu, dan sisanya dititipkan kepada tiga pemilik kartu di ujung lembah.'] },
      { chapterNumber: 43, title: 'Bagas Menahan Air Lereng', paragraphs: ['Bagas menutup pintu saluran lereng atas selama empat hari dan menyebutnya perbaikan mendadak. Enam petak layu bersama-sama, termasuk milik dua penanam yang ikut membawa salinan. Vina mencatat jam penutupan dari rumah masing-masing. Daun teh menguning di enam petak, dan para tetangga berhenti di pematang untuk melihat tanah retak di bawahnya.'] },
      { chapterNumber: 44, title: 'Petak Layu Dipotret Bersama', paragraphs: ['Vina meminjam kamera sekolah dan memotret enam petak layu bersama pemiliknya yang berdiri di pematang. Setiap foto diberi tanggal di belakangnya oleh pemilik petak sendiri. Bu Ningsih menyimpan gulungan filmnya di lemari kelas. Dalam setiap bingkai tampak pemilik petak, daun yang menggulung, pematang kering, dan papan tanggal yang mereka pegang setinggi dada.'] },
      { chapterNumber: 45, title: 'Camat Menerima Rombongan', paragraphs: ['Rombongan enam orang diterima di kantor kecamatan setelah menunggu sejak pagi. Vina membiarkan setiap pemilik petak berbicara sendiri dan hanya menyusun urutannya. Pegawai kecamatan mencatat dan meminta salinan foto. Pegawai itu menulis enam nama dan nomor kartu pada buku agenda kecamatan, lalu membubuhkan nomor halaman di salinan foto.'] },
      { chapterNumber: 46, title: 'Danu Kehilangan Giliran', paragraphs: ['Danu kehilangan giliran memetik selama dua pekan sesudah nama adiknya disebut di kecamatan. Ia tidak menyalahkan Vina dan hanya berkata agar berkasnya jangan berhenti. Vina menyerahkan upah simpanannya untuk belanja rumah. Danu membawa uang Vina ke pasar; malamnya mereka menghitung sisa beras dan menghapus minyak dari daftar belanja pekan itu.'] },
      { chapterNumber: 47, title: 'Saluran Tua Dibuka Ripto', paragraphs: ['Mbah Ripto membuka saluran tua yang sudah puluhan musim tidak dipakai agar enam petak memperoleh air sementara. Kerja itu memakan tiga hari dan punggungnya sakit berhari-hari. Vina bekerja di sampingnya sampai lumpur mengeras di lengan. Pada hari ketiga, air mulai merayap melalui saluran tua menuju petak pertama sementara keduanya masih mengangkat lumpur dengan cangkul.'] },
      { chapterNumber: 48, title: 'Pemeriksa Datang Tanpa Kabar', paragraphs: ['Pemeriksa dari kabupaten datang tanpa pemberitahuan dan meminta melihat pintu saluran serta buku pembagian. Bagas menyerahkan buku yang halamannya tidak lagi cocok dengan kartu warga. Vina menunjukkan salinan dan foto tanpa menaikkan suara. Pemeriksa membawa kedua berkas itu pergi bersamanya.'] },
      { chapterNumber: 49, title: 'Bagas Dipindah Kecamatan', paragraphs: ['Kabar pemindahan Bagas ke kantor kecamatan sampai ke balai pada sore hari. Enam pemegang kartu berkumpul di rumah Vina tanpa merayakan apa pun. Danu duduk paling dekat dengan pintu, masih menunggu giliran kerjanya kembali. Tidak ada yang bertepuk tangan; mata mereka beberapa kali beralih kepada Danu, yang masih belum dipanggil kembali bekerja.'] },
      { chapterNumber: 50, title: 'Papan Jadwal Dibaca Warga', paragraphs: ['Papan jadwal baru dipasang dengan angka yang dapat dibaca siapa pun dan disalin bebas. Vina berdiri di belakang, membiarkan penanam lain menjelaskannya kepada pendatang. Map salinan tetap berada di bangku ketika Vina melangkah mundur dan menyilangkan tangan di belakang punggungnya. Sebelum Vina pulang, tiga penanam bergantian menyalin angka papan dan seorang lainnya meluruskan sudut kertas yang terlepas.'] },
    ], justification: 'The first office confrontation leaves Vina ashamed and alone; later chapters shift to archive research, collective disclosure, photographic evidence, a district hearing, and self-built irrigation, each paid for with a visible cost.' },
    { chapters: [
      { chapterNumber: 6, title: 'Beranda Kantor Dibangun', paragraphs: ['Beranda kantor pengairan dibangun ulang dengan tirai tebal dan sebuah bel tali di tiangnya. Warga diberi tahu bahwa keluhan harus disampaikan melalui bel tersebut. Vina melihat pembangunan itu selesai dalam seminggu ketika mengantar benih. Saat melewati beranda, tangannya tetap pada keranjang benih dan tali bel bergoyang sendiri tertiup angin.'] },
      { chapterNumber: 14, title: 'Bel Pintu Tidak Dijawab', paragraphs: ['Vina membunyikan bel di beranda kantor untuk menanyakan mengapa jatah rumah lereng dipindah. Bagas berbicara dari balik tirai dan menyuruhnya menunggu surat. Vina berdiri sampai hujan turun, lalu pulang tanpa melihat wajah siapa pun. Penolakan yang tak tampak itu membuatnya merasa kecil dan mengira satu-satunya pilihan adalah membunyikan bel lebih keras esok hari.'] },
      { chapterNumber: 15, title: 'Kursi Kosong Menghadap Jalan', paragraphs: ['Alih-alih kembali ke beranda, Vina menaruh kursi kosong di simpang tempat keluarga menunggu air. Ia mengikatkan papan kecil bertuliskan jam kedatangan dan meminta setiap orang memindahkan satu kerikil ke bawah kursi saat petugas tidak muncul. Menjelang sore terkumpul sebelas kerikil. Keluhan yang kemarin terkurung di balik tirai kini memiliki tempat terbuka dan hitungan bersama.'] },
      { chapterNumber: 16, title: 'Sebelas Kerikil Dibawa Berjalan', paragraphs: ['Vina membagi sebelas kerikil kepada keluarga yang menunggu dan mengajak mereka berjalan ke gerbang tanpa berteriak. Setiap orang meletakkan batunya di pijakan pintu sambil menyebut jam kehilangan giliran. Bagas keluar karena pintunya tak dapat ditutup. Vina tidak lagi meminta jawaban sendirian; ia menjaga urutan suara agar pengalaman mereka tidak berubah menjadi satu keributan yang mudah ditolak.'] },
      { chapterNumber: 32, title: 'Beranda Dipenuhi Kursi', paragraphs: ['Ketika surat pemindahan jatah kembali diumumkan, warga membawa kursi dari rumah masing-masing dan menyusunnya di beranda kantor. Mereka duduk sesuai jam yang pernah dicatat, menyisakan satu kursi kosong untuk petugas yang harus menjawab. Bagas akhirnya membacakan dasar perubahan di depan mereka. Vina berdiri di simpang, bukan di depan tirai, dan mengetahui ruang menunggu kini mereka bentuk sendiri.'] },
      { chapterNumber: 41, title: 'Kursi Dirampas Petugas', paragraphs: ['Petugas mengangkut kursi warga dari beranda pada dini hari dan menumpuknya di belakang gudang kantor. Warga menemukan tumpukan itu ketika matahari naik. Vina mencatat jumlah kursi dan pemiliknya di kertas jatah lama. Keesokan paginya hanya lima keluarga datang; tiga pemilik kursi memilih tetap di rumah ketika Vina mengetuk pintu mereka.'] },
      { chapterNumber: 42, title: 'Tikar Menggantikan Kursi', paragraphs: ['Warga membawa tikar pandan yang mudah digulung dan digelar cepat di beranda. Duduk di tikar membuat barisan mereka lebih rapat daripada ketika memakai kursi. Vina tetap menjaga urutan bicara seperti pada hari-hari sebelumnya. Sebelas keluarga duduk menurut urutan lama, dan Vina membacakan kembali jam masing-masing sebelum orang pertama mulai bicara.'] },
      { chapterNumber: 43, title: 'Jam Tunggu Ditulis Tembok', paragraphs: ['Seseorang menuliskan jam kedatangan dan jam kepulangan pada tembok beranda memakai arang. Angka itu bertambah setiap hari dan terbaca dari jalan. Vina menyalinnya ke buku sebelum hujan menghapus sebagian. Tulisan arang memenuhi dinding luar sepanjang tiga depa dan dapat dibaca pedagang yang melintas di jalan.'] },
      { chapterNumber: 44, title: 'Tembok Dicat Ulang', paragraphs: ['Tembok beranda dicat putih dalam satu malam dan seluruh angka arang hilang. Warga berdiri memandangi cat yang masih basah pada pagi harinya. Vina membuka buku salinannya dan membacakan angka yang sempat ia pindahkan. Malam itu Laras membawa buku salinan pulang; pagi berikutnya ia menyerahkannya kepada Karsa di depan enam warga.'] },
      { chapterNumber: 45, title: 'Buku Salinan Dijaga Bergilir', paragraphs: ['Buku salinan berpindah menginap di rumah berbeda setiap malam menurut daftar yang disusun warga. Setiap penerima menandatangani halaman terakhir sebelum menyerahkannya. Vina tidak pernah memegangnya dua malam berturut-turut. Tujuh tanda tangan berbeda memenuhi halaman terakhir, dan nama penjaga malam berikutnya sudah tertulis di bawahnya. Daftar giliran menginap ditempel di dinding warung Laras.'] },
      { chapterNumber: 46, title: 'Vina Diusir Kios', paragraphs: ['Pemilik kios tempat Vina biasa membeli goni menolak melayaninya dan menyebut alasan persediaan. Ia berjalan lebih jauh ke kios kecamatan dengan ongkos yang tidak sedikit. Karsa kemudian membawakan goni untuknya tanpa diminta. Buku tunggunya tidak memuat ongkos jalan tambahan, telapak kakinya yang lecet, atau goni yang baru tiba setelah petang.'] },
      { chapterNumber: 47, title: 'Kursi Kosong Diberi Nama', paragraphs: ['Warga menuliskan nama jabatan petugas pada kursi kosong yang selalu disisakan di beranda. Kursi itu berdiri sendiri menghadap barisan tikar setiap hari. Seorang pegawai muda akhirnya duduk di sana dan mencatat keluhan selama dua jam. Pegawai muda itu menaruh buku agenda di pangkuannya, lalu memanggil nama pertama dari daftar yang dipegang Vina.'] },
      { chapterNumber: 48, title: 'Tirai Dibuka Siang', paragraphs: ['Tirai beranda dibuka pada siang hari karena pegawai muda itu meminta udara masuk. Warga melihat isi ruangan untuk pertama kalinya sejak beranda dibangun. Vina tidak masuk dan tetap duduk di tikar. Dari tikar, warga dapat melihat tiga meja, lemari surat, dan Bagas yang duduk di belakang tumpukan map.'] },
      { chapterNumber: 49, title: 'Bel Tali Dilepas', paragraphs: ['Bel tali di tiang beranda dilepas karena tidak ada lagi yang memakainya. Warga menyampaikan keluhan langsung kepada pegawai yang duduk di kursi bernama. Vina menyimpan tali bel itu di rumah tanpa alasan yang jelas. Ia merasa lega dan sekaligus lelah oleh musim yang panjang.'] },
      { chapterNumber: 50, title: 'Tikar Digelar Musim Baru', paragraphs: ['Musim baru dimulai dan tikar tetap digelar di beranda meski keluhan sudah dijawab di tempat. Warga memakainya untuk menunggu giliran dengan tenang. Vina datang terlambat dan menemukan tempatnya sudah disediakan orang lain. Seorang penanam menggeser tempat untuk Vina, sementara dua warga lain sudah memegang daftar urutan dan menuangkan air minum.'] },
    ], justification: 'An unseen office rejection changes into a public waiting record, an ordered collective walk, a chair occupation, and a durable shared practice, each stage answered by seizure, whitewash, or exclusion that the group must absorb.' },
    { chapters: [
      { chapterNumber: 6, title: 'Danu Menandatangani Kontrak', paragraphs: ['Danu menandatangani kontrak memetik teh untuk satu musim penuh di kantor kebun. Ia pulang membawa kartu pekerja dan topi baru yang masih kaku. Vina menyiapkan makan malam lebih banyak daripada biasanya untuk merayakannya. Kakaknya berkata pekerjaan itu akan menutup biaya rumah sampai panen.'] },
      { chapterNumber: 14, title: 'Pemetik Menunduk di Jalan', paragraphs: ['Danu pulang dari kebun teh dengan kepala tertunduk dan meminta Vina tidak menanyakan jatah air di kantor. Ia takut kontraknya dicabut. Vina setuju, menaruh kartu jatah di bawah mangkuk nasi, dan membiarkan pembicaraan berhenti. Malam itu ia merasa bersalah karena memilih ketenangan rumah daripada mengetahui alasan pemotongan.'] },
      { chapterNumber: 15, title: 'Upah Disalin dari Buku Warung', paragraphs: ['Di kedai lereng, penjaja teh bernama Laras menunjukkan buku utang yang dipakai pemetik membeli makan siang. Vina melihat beberapa nama dipotong dari daftar upah pada hari yang sama dengan jatah air berkurang. Ia tidak mengajak Danu ke kantor. Ia menyalin tanggal diam-diam dan menyadari ketakutan kakaknya menyembunyikan pola yang lebih luas.'] },
      { chapterNumber: 16, title: 'Makan Siang di Bawah Peneduh', paragraphs: ['Vina membawa nasi bungkus ke kebun dan duduk di bawah peneduh bersama tiga pemetik perempuan. Mereka awalnya diam, lalu satu orang menunjukkan telapak tangan yang terluka karena kerja tambahan. Vina membacakan tanggal dari buku warung tanpa menyebut nama pengadu. Danu mendengarnya dari jauh dan tidak marah; ia hanya menaruh keranjangnya lalu duduk lebih dekat.'] },
      { chapterNumber: 32, title: 'Kertas Upah di Pagar Barak', paragraphs: ['Ketika Bagas menempel jadwal baru di pagar barak, Vina menempel salinan pemotongan upah di sebelahnya. Para pemetik yang dulu menunduk berhenti membaca, termasuk Danu. Mandor memerintahkan kertas itu diturunkan, tetapi enam tangan sudah memegang sudutnya. Vina tidak lagi menyimpan kartu di bawah mangkuk; ia berdiri di samping kakaknya saat nama mereka dibaca keras.'] },
      { chapterNumber: 41, title: 'Buku Warung Diminta Kebun', paragraphs: ['Pengurus kebun meminta buku utang warung diserahkan dengan alasan pemeriksaan usaha. Laras menyalin seluruh halaman semalaman sebelum menyerahkannya. Vina membantu menyalin sampai matahari terbit dan tangannya kaku. Ketika buku asli dibawa pengurus kebun, bundel salinan tetap berada di meja Laras dengan seluruh tanggal dan angka terbaca. Salinan itu dijilid memakai benang jahit dan sampul kalender bekas.'] },
      { chapterNumber: 42, title: 'Pemetik Perempuan Berhitung', paragraphs: ['Tiga pemetik perempuan menghitung selisih upah mereka sendiri di bawah peneduh memakai lidi. Mereka menemukan potongan yang sama berulang pada hari pembagian air. Vina hanya menyediakan salinan dan tidak ikut menghitung. Masing-masing perempuan menyimpan susunan lidinya sendiri dan menyalin hasil hitungan ke belakang kartu pekerja.'] },
      { chapterNumber: 43, title: 'Peneduh Dibongkar Mandor', paragraphs: ['Peneduh bambu tempat mereka makan siang dibongkar dengan alasan mengganggu jalur pikul. Para pemetik makan di bawah terik selama sepekan berikutnya. Dua orang berhenti ikut berhitung karena takut. Pada hari ketujuh hanya satu dari tiga perempuan kembali membawa lidi; dua tempat makan lain tetap kosong. Bambu bekas peneduh diangkut ke gudang alat pada sore yang sama.'] },
      { chapterNumber: 44, title: 'Rumah Vina Jadi Tempat', paragraphs: ['Vina membuka dapur rumahnya sebagai tempat berkumpul sesudah kerja meski Danu ragu. Empat pemetik datang pada malam pertama membawa nasi sendiri. Danu menyediakan air panas tanpa banyak bicara. Empat pasang sandal berjajar di pintu dapur Vina, cukup jelas terlihat dari jalan yang menuju rumah mandor. Pintu dapur dibiarkan terbuka supaya tidak terdengar seperti rapat.'] },
      { chapterNumber: 45, title: 'Danu Bicara Pertama Kali', paragraphs: ['Danu menceritakan potongan upahnya sendiri di depan empat pemetik pada pertemuan ketiga. Ia menyebut angka yang selama ini disimpannya dari adiknya. Vina menuliskannya seperti keterangan orang lain tanpa memberi tanda khusus. Sesudah menyebut angka terakhir, Danu menggeser kartu pekerjanya di antara piring, lalu meminta Vina mencatat nama lengkapnya.'] },
      { chapterNumber: 46, title: 'Kontrak Danu Dicabut', paragraphs: ['Kontrak Danu dicabut pada awal pekan dengan alasan pengurangan pekerja musiman. Ia menyerahkan topi dan kartu pekerjanya di kantor kebun. Vina menunggunya di simpang jalan tanpa mengatakan apa pun. Topi yang dahulu mereka rayakan tergantung lagi pada paku dapur, kali ini tanpa kartu pekerja di bawahnya. Upah pekan terakhirnya dibayarkan dua hari kemudian tanpa surat penjelasan.'] },
      { chapterNumber: 47, title: 'Empat Nama Diserahkan Kecamatan', paragraphs: ['Empat pemetik menyerahkan keterangan bernama ke kantor kecamatan tanpa Vina ikut masuk. Mereka menunggu tanda terima sampai kantor tutup. Danu mengantar mereka pulang memakai sepeda pinjaman. Vina menunggu di rumah sementara empat pemetik membawa map, meminta tanda terima, dan menolak pulang sebelum mendapatkannya. Tanda terima bernomor akhirnya diserahkan pegawai keesokan paginya.'] },
      { chapterNumber: 48, title: 'Kebun Memanggil Pemetik', paragraphs: ['Kantor kebun memanggil pemetik satu per satu dan menawarkan pembayaran selisih tanpa surat. Tiga orang menolak menandatangani apa pun sebelum keterangannya dibaca. Satu orang menerima dan berhenti datang ke dapur Vina. Sore itu tiga perempuan kembali ke dapur membawa formulir kosong; kursi perempuan keempat tetap kosong setelah ia menerima uang.'] },
      { chapterNumber: 49, title: 'Danu Bekerja di Kanal', paragraphs: ['Danu memperoleh kerja harian membersihkan kanal terasering dengan upah lebih kecil daripada di kebun teh. Ia berangkat sebelum kabut turun dan pulang berlumpur. Vina membaginya bekal tanpa membicarakan kontrak yang hilang. Upah kanal hanya cukup untuk beras dan garam, sementara catatan utang goni tetap terselip di bawah kaleng dapur. Sepatu botnya bocor pada pekan kedua dan ditambal sendiri.'] },
      { chapterNumber: 50, title: 'Daftar Upah Ditempel Kebun', paragraphs: ['Daftar upah harian mulai ditempel di pagar barak setiap pekan atas keputusan pengurus baru. Pemetik membacanya sebelum berangkat dan menghitung sendiri. Danu tidak lagi bekerja di sana dan tetap berhenti membacanya dari jalan. Nama Danu tidak tercantum pada daftar; setelah membaca sampai baris terakhir, ia melanjutkan perjalanan menuju kanal.'] },
    ], justification: 'Home silence changes into wage-record research, a shifting meeting place, then public testimony where Danu joins rather than suppresses her, and the family absorbs the lost contract as the price.' },
    { chapters: [
      { chapterNumber: 6, title: 'Jam Pasir Diperbaiki Ripto', paragraphs: ['Mbah Ripto memperbaiki jam pasir warisan ayahnya dengan mengganti leher kaca yang retak. Ia menjelaskan kepada Vina bahwa alat itu dahulu dipakai membagi giliran sebelum kantor berdiri. Vina memperhatikan pasir turun sampai habis dua kali. Alat tersebut kembali diletakkan di rak rumah jaga sesudah selesai.'] },
      { chapterNumber: 14, title: 'Jam Pasir Ditarik dari Rak', paragraphs: ['Kru saluran mengambil jam pasir Mbah Ripto dari rumah jaga dan membawa alat itu ke kantor Bagas. Vina memohon dari kusen pintu agar jam itu dikembalikan karena warga memakai pasirnya untuk mengukur giliran. Bagas tertawa dan berkata warga tidak perlu alat yang membingungkan. Vina pulang dengan tangan kosong serta kemarahan yang ditelannya sendiri.'] },
      { chapterNumber: 15, title: 'Bayang Tiang Menjadi Penanda', paragraphs: ['Mbah Ripto tidak mengejar jam pasir itu. Ia menunjukkan pada Vina bagaimana bayang tiang bambu bergerak melintasi tiga batu pipih di halaman rumah jaga. Vina menunggu sampai bayang mencapai batu kedua dan menulis waktunya pada kulit bambu. Ia merasa heran karena sesuatu yang dirampas dapat diganti dengan langit yang tidak bisa dikunci kantor.'] },
      { chapterNumber: 16, title: 'Batu Pematang Diberi Garis', paragraphs: ['Vina mengajak dua anak sekolah memberi garis arang pada batu pematang sesuai bayang yang diajarkan Mbah Ripto. Mereka tertawa saat kaki mereka terkena lumpur, lalu mengulang pengukuran sampai garisnya cocok. Tindakan kecil itu membuat Vina merasa tidak sendirian lagi. Ia menyimpan catatan baru di dalam botol kaca, bukan di tempat yang dapat dirampas mudah.'] },
      { chapterNumber: 32, title: 'Bayang Menyangkal Jam Kantor', paragraphs: ['Pada hari pembagian, petugas kantor mengklaim gerbang dibuka tepat waktu. Vina membawa botol berisi catatan bayang dan menunjukkan tiga batu yang telah dilihat anak-anak sekolah setiap pagi. Mbah Ripto berdiri di belakangnya tanpa mengambil alih. Ketika bayang tiba di garis kedua sebelum jam kantor berbunyi, warga bersorak dan Vina tersenyum untuk pertama kalinya dalam sengketa itu.'] },
      { chapterNumber: 41, title: 'Batu Pematang Dicabut Malam', paragraphs: ['Tiga batu pipih bertanda arang dicabut pada malam hari dan dibuang ke parit bawah. Anak sekolah menemukan lubangnya ketika berangkat pagi. Vina menahan diri untuk tidak menuduh siapa pun di depan mereka. Sehari sebelumnya warga bersorak di sekitar tiga batu itu; pagi ini hanya tiga lubang rata yang tersisa. Bekas lubangnya ditutup tanah kering yang diinjak rata.'] },
      { chapterNumber: 42, title: 'Tiang Bambu Ditanam Dalam', paragraphs: ['Mbah Ripto menanam tiang bambu baru lebih dalam dan mengecor kakinya dengan campuran kapur. Vina menandai bayangnya memakai paku pada lantai semen halaman. Bekas paku tertanam di lantai semen, dan ketika Vina menggosoknya dengan telapak, garis itu tetap terlihat. Pekerjaan itu memakan dua hari dan seluruh persediaan kapur rumah jaga.'] },
      { chapterNumber: 43, title: 'Halaman Dinyatakan Tanah Kantor', paragraphs: ['Kantor mengumumkan halaman rumah jaga termasuk tanah pengairan dan melarang pemasangan alat di sana. Warga diminta menjauh dari tiang bambu tersebut. Mbah Ripto menolak menandatangani pengumuman itu. Nama Mbah Ripto dan nomor rumah jaga tercetak pada bagian bawah pengumuman, tepat di atas batas waktu pengosongan. Pengumuman itu ditempel di tiga tempat sekaligus pada hari yang sama.'] },
      { chapterNumber: 44, title: 'Bayang Diukur Halaman Sekolah', paragraphs: ['Vina memindahkan pengukuran ke halaman sekolah dengan izin Bu Ningsih dan memakai tiang bendera. Murid-murid menandai bayang pada jam istirahat sebagai kegiatan kelas. Catatan itu masuk buku kegiatan sekolah yang resmi. Setiap siang tiga puluh murid berkumpul di tiang bendera, sementara Bu Ningsih mencatat hasilnya dalam buku kegiatan kelas.'] },
      { chapterNumber: 45, title: 'Buku Kelas Menjadi Bukti', paragraphs: ['Buku kegiatan kelas memuat waktu bayang selama tiga puluh hari berturut-turut dengan tanda tangan guru. Vina meminta salinannya untuk dibawa ke kecamatan. Bu Ningsih menyerahkannya beserta surat pengantar sekolah. Nama Bu Ningsih, tanda tangannya, dan cap sekolah muncul pada setiap halaman di bawah tiga puluh catatan waktu. Cap sekolah dibubuhkan pada setiap halaman salinan tersebut.'] },
      { chapterNumber: 46, title: 'Ripto Diminta Pindah', paragraphs: ['Mbah Ripto diminta mengosongkan rumah jaga dalam tiga puluh hari karena statusnya disebut tidak resmi. Ia mengemas alat-alat tuanya ke dalam peti kayu. Vina menampungnya di kamar belakang rumahnya. Peti Mbah Ripto memenuhi kamar belakang, sedangkan tikar tidurnya terbentang di antara karung benih dan dinding dapur Vina.'] },
      { chapterNumber: 47, title: 'Pemeriksa Menghitung Bayang', paragraphs: ['Pemeriksa kabupaten datang pagi hari dan menghitung bayang tiang bendera bersama murid kelas enam. Ia mencocokkannya dengan buku pembagian kantor dan menemukan selisih empat puluh menit. Vina berdiri di belakang barisan murid tanpa bicara. Pemeriksa menulis “40 menit” pada formulirnya sendiri lalu meminta guru dan dua murid menandatangani bagian saksi.'] },
      { chapterNumber: 48, title: 'Gerbang Dibuka Lebih Awal', paragraphs: ['Gerbang saluran mulai dibuka empat puluh menit lebih awal sesuai hasil pemeriksaan. Penanam lereng atas menerima air sebelum kabut naik untuk pertama kalinya. Vina memandanginya dari pematang bersama Mbah Ripto. Orang tua itu tidak berkata apa-apa dan hanya duduk lama.'] },
      { chapterNumber: 49, title: 'Rumah Jaga Dikunci', paragraphs: ['Rumah jaga dikunci dan papannya diganti menjadi gudang alat kantor. Mbah Ripto tetap tinggal di kamar belakang rumah Vina sampai musim berganti. Ia berhenti berbicara tentang jam pasir maupun bayang tiang. Gerbang kini terbuka lebih pagi, tetapi kunci rumah jaga masih tergantung pada dinding kantor dan tikar Ripto terbentang di kamar Vina. Peti perkakasnya dititipkan di kolong dipan kamar belakang.'] },
      { chapterNumber: 50, title: 'Tiang Bendera Diberi Skala', paragraphs: ['Sekolah mengecat skala permanen di halaman untuk mengukur bayang setiap pagi sebagai pelajaran. Murid baru mempelajarinya tanpa mengetahui asal usulnya. Vina menghadiri upacara pengecatan dan berdiri di barisan orang tua. Murid-murid mengikuti garis cat dari tiang bendera, sementara Mbah Ripto menyaksikan mereka dari kamar belakang rumah Vina.'] },
    ], justification: 'After the official timepiece is seized, Vina changes evidence source to shadows, moves the method to school ground when the yard is claimed, and wins an earlier gate at the price of Mbah Ripto losing his home.' },
    { chapters: [
      { chapterNumber: 6, title: 'Lumbung Diserahkan Vina', paragraphs: ['Kunci lumbung benih diserahkan kepada Vina sesudah penjaga sebelumnya pulang ke kampung istrinya. Ia diminta mencatat setiap karung yang masuk dan keluar pada buku bersampul cokelat. Bagas menandatangani serah terima tanpa membaca isinya. Vina membersihkan lantai lumbung sepanjang hari pertama.'] },
      { chapterNumber: 14, title: 'Benih Diletakkan di Lantai', paragraphs: ['Bagas datang ke lumbung dan menunjuk tiga karung yang harus diberikan kepada kru saluran tanpa dicatat. Vina menurunkan karung itu ke lantai seperti diminta dan tidak mengatakan apa-apa. Setelah mandor pergi, ia duduk lama di samping debu bekas karung. Ia merasa dirinya ikut menjaga kebiasaan yang merugikan penanam lain.'] },
      { chapterNumber: 15, title: 'Tali Rafia Berwarna Kuning', paragraphs: ['Vina tidak lagi menyimpan catatan di buku yang mudah dibaca Bagas. Ia mengikat setiap karung keluar dengan tali rafia kuning dan menyimpan potongan pasangannya dalam kaleng teh. Saat kru datang lagi, ia tetap menyerahkan karung, tetapi kini jumlahnya dapat dihitung dari potongan tali. Rasa bersalahnya belum hilang, namun ia mulai mencari cara tanpa menantang langsung.'] },
      { chapterNumber: 16, title: 'Kaleng Teh Dipinjam Bu Ningsih', paragraphs: ['Bu Ningsih melihat kaleng teh penuh potongan rafia dan meminta Vina menjelaskan artinya. Vina mengajaknya menghitung bersama di ruang kelas, lalu membuat daftar warna dan tanggal. Guru itu tidak memuji atau menghibur; ia meminta Vina memilih apakah daftar tersebut akan disimpan atau diperlihatkan. Vina menjawab akan memperlihatkannya saat jumlahnya cukup.'] },
      { chapterNumber: 32, title: 'Rafia Kuning Digantung di Balai', paragraphs: ['Pada rapat balai, Vina menggantung tiga puluh tujuh potongan tali kuning pada batang bambu menurut tanggal keluar karung. Bagas menyebut itu barang sepele, tetapi Bu Ningsih membacakan daftar pasangannya. Penanam melihat berapa banyak yang tidak pernah masuk buku penerimaan. Vina masih takut, namun kali ini ia memilih memegang ujung batang bambu sampai rapat selesai.'] },
      { chapterNumber: 41, title: 'Rafia Kuning Dilarang Dipakai', paragraphs: ['Bagas memerintahkan seluruh karung diikat memakai tali goni polos dan melarang rafia berwarna. Persediaan rafia kuning di lumbung disingkirkan pada hari yang sama. Vina menyerahkannya tanpa membantah di depan kru. Saat karung pertama keluar dengan tali goni polos, Vina tidak memperoleh potongan kuning untuk dimasukkan ke kaleng teh. Gulungan rafia itu dibakar bersama sampah kebun sore harinya.'] },
      { chapterNumber: 42, title: 'Jahitan Goni Diberi Tanda', paragraphs: ['Vina menjahit satu tusuk benang merah pada mulut setiap karung yang keluar tanpa dicatat. Tusukan itu tidak terlihat kecuali karung dibalik. Ia menyimpan gulungan benang di dalam kaleng gula. Pada sore pertama, tiga karung bertusuk merah meninggalkan lumbung tanpa satu pun kru membalik bagian mulut karung. Jarumnya ia tusukkan pada gabus tutup kaleng agar tidak hilang.'] },
      { chapterNumber: 43, title: 'Karung Kembali Berlubang', paragraphs: ['Empat karung kembali ke lumbung dalam keadaan berlubang dan benihnya bercampur sekam. Bagas menuduh Vina lalai menjaga persediaan dan memotong upahnya sebulan. Ia menerima potongan itu tanpa menyebut tusukan benang. Sesudah potongan upah, kaleng minyak di dapurnya kosong dan Danu mengikis sisa lemak dari dasar wajan. Bulan itu keluarganya makan tanpa membeli minyak goreng baru.'] },
      { chapterNumber: 44, title: 'Karsa Menghitung di Jalan', paragraphs: ['Karsa yang berkeliling menjual bibit mulai memperhatikan karung bertusuk merah di gudang desa lain. Ia mencatat tempat dan tanggalnya lalu menyerahkannya kepada Vina. Karsa menyerahkan tiga kertas pembungkus berisi nama desa dan tanggal sebelum Vina sempat menanyakan perjalanan dagangnya. Nama dua gudang desa lain kini tercatat di samping tanggal keluarnya karung dari lumbung Vina. Nama desa dan tanggalnya ditulis Karsa pada kertas pembungkus bibit.'] },
      { chapterNumber: 45, title: 'Gudang Desa Lain Didatangi', paragraphs: ['Vina berjalan setengah hari menuju gudang desa sebelah bersama Karsa untuk melihat karung tersebut. Penjaga gudang mengizinkan mereka membalik dua karung. Tusukan benang merah itu masih ada pada keduanya. Vina menunjuk dua tusukan merah itu, lalu Karsa menuliskan nama gudang dan nomor karung di kertas pembungkus bibit.'] },
      { chapterNumber: 46, title: 'Kunci Lumbung Diambil', paragraphs: ['Kunci lumbung diambil dari Vina dan diserahkan kepada seorang kru saluran tanpa alasan tertulis. Ia mengosongkan meja kerjanya pada sore yang sama. Buku bersampul cokelat itu ia tinggalkan sesuai aturan. Kaleng gula berisi benang merah ia bawa pulang. Kru pengganti itu menerima kunci tanpa daftar barang.'] },
      { chapterNumber: 47, title: 'Keterangan Karsa Ditandatangani', paragraphs: ['Karsa menandatangani keterangan tentang karung bertusuk merah di hadapan pegawai kecamatan. Ia mempertaruhkan izin dagang kelilingnya dengan melakukan itu. Vina menyerahkan kaleng benang sebagai barang pendukung. Nama dan tanda tangan Karsa tercantum pada formulir kecamatan, sementara kolom pekerjaan menyebutnya sebagai pedagang bibit keliling. Izin dagangnya berlaku sampai akhir tahun berjalan.'] },
      { chapterNumber: 48, title: 'Lumbung Diperiksa Kabupaten', paragraphs: ['Pemeriksa kabupaten membalik karung di lumbung dan menghitung jahitan merah selama dua hari. Kru saluran yang memegang kunci tidak dapat menerangkan selisihnya. Vina dipanggil hanya untuk menerangkan cara jahitan itu dibuat. Ia menjawab singkat lalu keluar tanpa menunggu hasilnya. Pemeriksa itu memotret dua karung sebelum menutup berita acara.'] },
      { chapterNumber: 49, title: 'Vina Menanam Sendiri', paragraphs: ['Tanpa pekerjaan lumbung, Vina menggarap petak kecil di belakang rumah memakai benih simpanannya. Ia bekerja lebih keras dengan penghasilan yang lebih tipis daripada sebelumnya. Karsa menitipkan bibit tambahan setiap kali lewat. Ia tidak meminta kunci lumbung itu kembali kepada siapa pun.'] },
      { chapterNumber: 50, title: 'Buku Lumbung Dibuka Umum', paragraphs: ['Buku keluar masuk lumbung mulai ditempel salinannya di balai setiap pekan. Penanam membaca dan menghitung sendiri sebelum meminta benih. Vina membacanya sekali lalu kembali ke petaknya. Aturan baru itu berlaku untuk lumbung yang tidak lagi ia jaga. Salinan pertama ditempel pada papan di sebelah pengumuman pajak.'] },
    ], justification: 'The sack demand evolves from silent compliance to covert stitched tracking, an outside witness, and a district inspection, with Vina losing her wage, her keys, and her post as the cost.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 6, title: 'Kartu Diterima Balai', paragraphs: ['Vina menerima kartu jatah air di balai bersama penanam lain pada awal musim. Petugas membacakan aturan pemakaian dengan suara datar. Ia memasukkan kartu itu ke saku baju dan pulang menyusuri pematang. Malam itu kartu tetap terlipat di saku bajunya sampai baju tersebut digantung di belakang pintu.'] },
      { chapterNumber: 14, title: 'Kartu Ditepis Pertama Kali', paragraphs: ['Vina memperlihatkan kartu jatah pada Bagas di kantor dan mengatakan angka biru itu salah. Mandor menjawab bahwa penanam kecil selalu ingin lebih. Vina menunduk, memasukkan kartu ke saku, lalu pulang lewat jalan yang sama. Di rumah ia mengingat setiap kata kasar itu tanpa menemukan informasi, tindakan, atau perasaan baru selain malu.'] },
      { chapterNumber: 15, title: 'Kartu Ditepis Kedua Kali', paragraphs: ['Esoknya Vina membawa kartu ke meja kantor lagi dengan pertanyaan yang tidak banyak berubah. Bagas menjawab bahwa petak kecil tidak layak meminta tambahan. Jari Vina gemetar saat menyelipkan kartunya ke lengan baju, lalu ia memilih jalur kebun singkong menuju rumah. Di dapur, ucapan itu berputar di kepalanya tanpa meninggalkan bukti, penolong, maupun sikap baru.'] },
      { chapterNumber: 16, title: 'Kartu Ditepis Ketiga Kali', paragraphs: ['Pagi sesudahnya Vina kembali ke kantor, meletakkan kartu di dekat buku Bagas, dan memakai susunan pertanyaan hampir serupa. Mandor memberi alasan lama sambil menutup bukunya. Vina meremas kartu hingga ujungnya kusut, menyusuri jalan dekat kebun kopi, lalu tiba di rumah setelah gelap. Malam itu rasa malunya tidak memberi keputusan atau pengetahuan yang membedakan hari ketiga dari hari pertama.'] },
      { chapterNumber: 32, title: 'Kartu Ditepis Bulan Berikutnya', paragraphs: ['Delapan belas hari kemudian Vina membawa kartu lama ke ruangan Bagas dan menunggu di samping lemari arsip. Mandor menolak permintaannya dengan jawaban yang dulu juga dipakai. Vina melipat kartunya menjadi dua dan pulang melewati jembatan bambu. Tidak muncul cara, tempat, informasi, atau akibat perasaan yang membedakan kunjungan itu dari kegagalan sebelumnya.'] },
      { chapterNumber: 41, title: 'Kartu Ditepis Pagi Berkabut', paragraphs: ['Kabut masih menutup lereng ketika Vina kembali meletakkan kartu jatah di meja kantor Bagas. Ia mengatakan angka biru itu tidak cukup bagi petaknya. Bagas menyebut pemilik lahan sempit gemar meminta tambahan, kemudian menggeser kartu menuju sudut meja. Vina memasukkannya ke saku; buku Bagas tetap tertutup ketika ia keluar dan berjalan pulang lewat jalan kantor.'] },
      { chapterNumber: 42, title: 'Kartu Ditepis Setelah Hujan', paragraphs: ['Sesudah hujan reda, Vina mendatangi meja yang sama dan membuka kartu pada bagian angka biru. Bagas tidak mengambilnya. Ia mengulang jawaban tentang luas petak kecil sambil merapikan buku di depannya. Vina menutup kartu, menyelipkannya ke lengan baju, lalu berjalan pulang sendirian melalui jalan kantor yang masih basah.'] },
      { chapterNumber: 43, title: 'Kartu Ditepis Siang Terik', paragraphs: ['Siang terik membuat ruang kantor pengairan pengap ketika Vina menunjukkan kartunya lagi. Pertanyaannya mengenai angka biru dijawab Bagas dengan kalimat lama tentang penanam kecil. Ia berdiri beberapa saat di depan meja tertutup, kemudian memasukkan kartu ke saku. Ia pulang lewat jalan kantor dengan kartu tetap di saku; kedua tangannya kosong ketika melewati gerbang.'] },
      { chapterNumber: 44, title: 'Kartu Ditepis Sore Berangin', paragraphs: ['Angin sore menggoyangkan tirai kantor saat Vina menaruh kartu dekat buku Bagas. Ia menyebut kekurangan jatah pada petaknya, dan mandor kembali mengatakan penanam kecil selalu ingin tambahan. Vina mengambil kartu yang didorong ke arahnya. Ia meninggalkan ruangan, melewati gerbang, dan tetap menggenggam ujung saku tempat kartu itu disimpan sampai rumah.'] },
      { chapterNumber: 45, title: 'Kartu Ditepis Hari Pasar', paragraphs: ['Pada hari pasar Vina menunggu warga lain keluar sebelum mendekati meja Bagas. Ia membuka kartu pada lipatan yang sama dan menanyakan angka biru. Tanpa mengangkat kepala, Bagas berkata lahan seluas itu telah menerima bagiannya. Vina menyimpan kartu dan melewati keramaian; dua penanam yang berdiri dekat pintu dibiarkannya berlalu tanpa disapa.'] },
      { chapterNumber: 46, title: 'Kartu Ditepis Kantor Sepi', paragraphs: ['Kantor sepi ketika Vina meletakkan kartu jatah di hadapan Bagas. Ia mengulang pertanyaan mengenai angka biru. Bagas menyebut permintaannya berlebihan untuk lahan sempit, lalu menutup buku sebelum Vina selesai berdiri. Vina memasukkan kartu ke saku, keluar setelah Bagas menutup buku, dan berjalan pulang saat kantor tetap sepi.'] },
      { chapterNumber: 47, title: 'Kartu Ditepis Sebelum Tutup', paragraphs: ['Menjelang kantor tutup, Vina masih sempat menunjukkan kartu kepada Bagas dan menyebut petaknya yang kekurangan air. Mandor menunjuk angka biru lalu mengulang alasan tentang luas lahan. Petugas lain menutup jendela saat Vina memasukkan kartu ke lengan baju. Petugas lain sudah mengunci jendela ketika Vina berbelok ke jalur berbatu dan meninggalkan halaman kantor.'] },
      { chapterNumber: 48, title: 'Kartu Ditepis Sekali Lagi', paragraphs: ['Vina meratakan kartu yang lipatannya mulai memutih di atas meja Bagas. Ia menunjuk angka biru dan bertanya berapa jam air yang akan mencapai petaknya minggu itu. Mandor mendorong kartu tersebut kembali sambil berkata petak kecil tidak pantas memperoleh tambahan. Vina mengambilnya dan meninggalkan ruangan; permukaan kartu tetap hanya memuat angka biru lama ketika ia menyusuri jalan kantor.'] },
      { chapterNumber: 49, title: 'Kartu Disimpan Lemari', paragraphs: ['Bagas kembali menyebut luas petaknya, lalu Vina pulang membawa kartu di saku. Ia meletakkannya dalam lemari pakaian dan menutup pintunya. Meja di kamarnya hanya berisi kartu terlipat dan pensil yang tetap berada di dalam cangkir. Pagi berikutnya kartu itu diambil lagi untuk dibawa menuju meja Bagas melalui jalan kantor yang biasa.'] },
      { chapterNumber: 50, title: 'Kartu Baru Ditepis', paragraphs: ['Awal musim baru membawa Vina ke kantor dengan kartu jatah baru. Ia membuka angka biru di depan Bagas dan menanyakan tambahan untuk petaknya. Bagas berkata luas lahan itu tidak pantas memperoleh lebih, lalu mendorong kartu kembali. Vina menyimpannya di saku; Bagas sudah menunduk ke bukunya ketika ia pulang melalui jalur kantor.'] },
    ], justification: 'Every scene repeats the identical office approach, reply, route home, and shame; only weather, hour, and crowd change while tactic, information, and consequence stay fixed.' },
    { chapters: [
      { chapterNumber: 6, title: 'Tirai Beranda Dipasang', paragraphs: ['Tirai tebal dipasang di beranda kantor pengairan agar ruangan dalam tidak terlihat dari luar. Petugas menerangkan bahwa keluhan disampaikan melalui tali bel di tiang. Vina mendengar penjelasan itu sambil lewat mengantar goni. Ia melewati tiang tanpa menyentuh talinya dan meneruskan langkah menuju lumbung.'] },
      { chapterNumber: 14, title: 'Bel Dibunyikan Pagi', paragraphs: ['Vina membunyikan bel kantor dan meminta penjelasan tentang jatah yang dipindah. Bagas menjawab dari balik tirai bahwa surat belum selesai. Vina menunggu di bangku sampai matahari naik, lalu pulang tanpa nama petugas atau tanggal keputusan. Ia membawa kesal yang sama dan tidak mencatat berapa lama pintu itu membiarkannya sendiri.'] },
      { chapterNumber: 15, title: 'Bel Dibunyikan Menjelang Hujan', paragraphs: ['Keesokan hari Vina kembali ke beranda, menarik tali bel, dan mengulang pertanyaan dengan susunan serupa. Suara dari balik tirai kembali menyebut surat yang belum selesai. Ia berdiri sampai rintik datang lalu pergi tanpa mengajak keluarga lain, menandai waktu, atau mencoba pintu berbeda. Penantian kedua tidak mengubah siapa pun yang terlihat maupun apa yang diketahui.'] },
      { chapterNumber: 16, title: 'Bel Dibunyikan Ketiga', paragraphs: ['Pagi ketiga Vina menarik tali yang sama dan mendengar jawaban yang sama dari ruangan tertutup. Ia menekan telapak ke kusen, menunggu beberapa saat, lalu pulang lewat simpang. Tidak ada kursi dipindah, kerikil dihitung, atau saksi dipanggil. Beranda kembali kosong dan rasa kecilnya hanya mengulang bentuk dua kunjungan sebelumnya.'] },
      { chapterNumber: 32, title: 'Bel Masih Menjawab Tirai', paragraphs: ['Beberapa minggu kemudian Vina mendatangi beranda lagi dan membunyikan bel tanpa membawa catatan. Bagas tetap berbicara dari balik tirai tentang surat yang belum selesai. Vina duduk di bangku lama sampai siang lalu pulang sendiri. Jarak waktu tidak menghasilkan taktik, informasi, hubungan, atau akibat baru; penolakan itu tetap sebuah suara tanpa wajah.'] },
      { chapterNumber: 41, title: 'Bel Ditarik Musim Kemarau', paragraphs: ['Pada awal kemarau Vina membunyikan bel dan menanyakan surat yang belum juga datang. Suara tersembunyi mengulang berkas sedang ditata di ruang belakang. Ia menunggu di bangku sampai bayang tiang memendek, kemudian kembali ke rumah. Saat pulang, saku Vina tetap kosong dan bangku beranda kembali tidak ditempati siapa pun.'] },
      { chapterNumber: 42, title: 'Bel Ditarik Sesudah Subuh', paragraphs: ['Pagi buta Vina sudah berada di beranda lalu menarik tali kuningan dua kali. Dari balik tirai terdengar lagi bahwa berkas sedang disusun. Ia duduk sendirian sampai matahari penuh lalu berjalan pulang. Pensil tetap berada di rumah, dan bangku sebelahnya tidak diduduki hingga Vina beranjak. Embun pada bangku beranda membasahi bagian belakang bajunya.'] },
      { chapterNumber: 43, title: 'Bel Ditarik Sambil Berteduh', paragraphs: ['Hujan deras menemani Vina membunyikan bel sambil berteduh di bawah atap beranda. Dari ruang tertutup, Bagas kembali berkata suratnya masih disusun. Ia menunggu sampai hujan reda sebelum pergi. Bagas tidak membuka tirai atau menyebut tanggal. Air talang jatuh tepat di depan sepatunya.'] },
      { chapterNumber: 44, title: 'Bel Ditarik Hari Ramai', paragraphs: ['Beranda ramai oleh warga yang menunggu urusan lain ketika Vina menarik tali bel. Ia bertanya kapan surat pemindahan jatah dapat dibaca warga. Dari balik tirai, Bagas kembali berkata surat masih disusun. Vina pulang tanpa berbicara kepada seorang pun yang menunggu di sana. Sebagian warga itu membawa map berwarna cokelat serupa.'] },
      { chapterNumber: 45, title: 'Bel Ditarik Hari Sepi', paragraphs: ['Beranda kosong ketika Vina membunyikan bel tiga kali berturut-turut. Dari balik tirai terdengar petugas masih merapikan dokumen tersebut di belakang tirai. Perempuan itu duduk sampai lapar, lalu meninggalkan beranda kosong tanpa membuka payungnya. Bunyi bel terdengar sumbang pada tarikan ketiga dan memantul ke halaman.'] },
      { chapterNumber: 46, title: 'Bel Ditarik Bawa Payung', paragraphs: ['Pada siang mendung Vina membawa payung dan membunyikan bel. Vina menanyakan tanggal surat; Bagas menjawab bahwa berkas masih disusun. Vina bertahan hingga bayang tiang mencapai anak tangga terakhir, lalu pergi dengan payung tetap di tangannya. Payung tersebut tetap terlipat sepanjang perjalanan pulang. Mendung siang itu tidak pernah berubah menjadi hujan.'] },
      { chapterNumber: 47, title: 'Bel Ditarik Sesudah Panen', paragraphs: ['Seusai panen, Vina mendatangi beranda dan menarik tali bel sekali. Jawaban tersembunyi kembali mengatakan berkas belum rampung. Setelah menunggu, ia pulang; Bagas tidak menyebut tanggal sebelum langkah Vina mencapai simpang. Bau daun teh kering menempel pada bajunya. Pikul pekerja memenuhi jalan pulang.'] },
      { chapterNumber: 48, title: 'Bel Ditarik Lebih Keras', paragraphs: ['Vina menarik tali bel lebih keras sampai bunyinya terdengar ke jalan. Beberapa saat kemudian Dari balik kain, Bagas menjawab bahwa dokumen pemindahan masih disusun oleh petugas di ruang dalam. Ia duduk sebentar kemudian pulang menyusuri simpang, sementara seorang anak di jalan menoleh mendengar bunyi tersebut.'] },
      { chapterNumber: 49, title: 'Bel Didengar dari Rumah', paragraphs: ['Malam itu Vina teringat bunyi bel tersebut ketika berbaring di kamarnya. Ia menghitung berapa kali sudah menariknya dan berhenti sebelum selesai. Tidak ada yang ia ceritakan kepada Danu. Saat hitungan mencapai sebelas, ia menarik selimut sampai bahu lalu memejamkan mata. Kamarnya gelap sampai pagi.'] },
      { chapterNumber: 50, title: 'Bel Ditarik Musim Baru', paragraphs: ['Awal musim berikutnya membawa Vina kembali ke bel pada beranda serupa. Dari balik kain, Bagas berkata surat masih disusun tanpa menampakkan wajahnya. Ia menunggu di bangku sebelum pulang sendirian. Ketika Vina pergi, tirai tetap tertutup dan suara Bagas tidak terdengar lagi dari halaman. Tirainya kini memakai kain lebih tebal.'] },
    ], justification: 'Every office-bell visit repeats the hidden reply, solitary wait, and retreat; season, weather, and crowd shift while tactic, witness, record, and consequence never do.' },
    { chapters: [
      { chapterNumber: 6, title: 'Danu Membawa Topi', paragraphs: ['Danu pulang membawa topi pemetik yang baru dan meletakkannya di paku dekat pintu dapur. Ia berkata pekerjaan di kebun teh cukup untuk menutup belanja rumah. Vina menyiapkan teh untuk keduanya malam itu. Kartu jatah air masih tergeletak di meja tanpa dibicarakan.'] },
      { chapterNumber: 14, title: 'Danu Diminta Diam', paragraphs: ['Saat makan malam, Vina menyinggung air yang tinggal sedikit di halaman belakang. Danu mengusap jemarinya yang berbau teh dan meminta adiknya tidak mendatangi kantor sebab pekerjaannya belum aman. Kartu jatah ia letakkan di bawah serbet, lalu pembicaraan berbelok ke lauk. Rintik hujan memukul genting sampai keduanya berhenti bicara tanpa memperoleh jawaban.'] },
      { chapterNumber: 15, title: 'Danu Diminta Diam Lagi', paragraphs: ['Dua malam kemudian Vina menunjukkan tanah retak di telapak sepatunya kepada Danu. Kakaknya menunduk, berkata mandor dapat mencoret namanya bila keluarga mereka ribut, lalu meminta soal itu ditunda. Vina menyelipkan kartu ke lipatan taplak meja dan mengaduk nasi yang mulai dingin. Hujan gerimis terdengar dari dapur, sementara alasan lama membuat mereka berhenti lagi.'] },
      { chapterNumber: 16, title: 'Danu Meminta Hening', paragraphs: ['Pada malam ketiga Vina bertanya apakah kebun teh benar-benar mengancam pekerjaan Danu. Danu menaruh sendok, menyebut kontraknya hanya dapat bertahan bila rumah mereka tidak menimbulkan keributan, lalu mengalihkan mata ke jendela. Vina menyimpan kartu di bawah kain lap dekat tungku. Gerimis jatuh di halaman, dan rasa bersalahnya tinggal tanpa pilihan atau hubungan baru.'] },
      { chapterNumber: 32, title: 'Danu Menolak Bicara Kembali', paragraphs: ['Beberapa minggu setelahnya Vina menyebut bahwa bak mandi hampir kosong sebelum Danu pulang. Kakaknya menjawab pekerjaannya di kebun teh dapat lenyap bila mereka menantang kantor, lalu menutup pembicaraan dengan mengambil nasi lagi. Vina memasukkan kartu ke dalam wadah sendok dan menatap api tungku. Bunyi hujan kembali memenuhi dapur, tanpa kabar, tindakan, atau perasaan yang berbeda dari tiga malam sebelumnya.'] },
      { chapterNumber: 41, title: 'Danu Diam Saat Kabut', paragraphs: ['Kabut masuk sampai ke dapur ketika Vina menyinggung jatah air yang kembali dipotong. Danu meminta hal itu tidak dibawa ke kantor karena pekerjaannya belum aman. Kartu diselipkan ke bawah tatakan gelas. Keduanya menghabiskan makan malam tanpa melanjutkan pembicaraan. Kabut itu baru turun kembali menjelang keduanya mencuci piring.'] },
      { chapterNumber: 42, title: 'Danu Diam Sesudah Lembur', paragraphs: ['Danu pulang lembur dan Vina menunggunya dengan nasi yang sudah dingin. Ia menyebut petak belakang yang mengering, dan kakaknya meminta persoalan itu ditunda. Kartu disimpan di bawah tudung saji. Sesudah Danu meminta penundaan, keduanya hanya mendengar nasi dingin mendesis saat dihangatkan di atas tungku kecil.'] },
      { chapterNumber: 43, title: 'Danu Diam Malam Hujan', paragraphs: ['Hujan menahan mereka di dapur ketika Vina kembali menyinggung pemotongan jatah. Danu takut pekerjaannya dicabut bila keluarga mereka memicu keributan. Kartu masuk ke bawah nampan. Keduanya mendengarkan hujan sampai percakapan berhenti. Atap seng bocor pada satu titik di sudut. Ember ditaruh di bawahnya tanpa dibicarakan.'] },
      { chapterNumber: 44, title: 'Danu Diam Sebelum Berangkat', paragraphs: ['Sebelum berangkat pagi, Danu melarang Vina pergi ke kantor pengairan hari itu. Vina menjawab bahwa petak belakang belum menerima aliran. Ia menyelipkan kartu di balik wadah gula. Kabut mulai terangkat ketika Danu mengambil bekalnya dan Vina tetap berdiri di dekat wadah gula. Danu membawa bekal yang tutupnya belum rapat lalu berjalan menuju kebun.'] },
      { chapterNumber: 45, title: 'Danu Diam Hari Libur', paragraphs: ['Pada hari libur, Vina kembali menyebut petak belakang yang belum menerima air. Danu meminta hal itu didiamkan dulu sampai kontraknya lebih aman. Kartu tetap tertutup di bawah kaleng garam sementara Danu mencuci piring makan siang tanpa diminta. Halaman rumah mereka kering sepanjang hari.'] },
      { chapterNumber: 46, title: 'Danu Diam Sesudah Sakit', paragraphs: ['Demam Danu baru reda ketika Vina kembali menyebut jatah yang belum dibetulkan. Danu berkata kontraknya dapat dicabut bila Vina pergi ke kantor dan menyuruhnya menunggu. Vina menaruh kartu di balik kotak obat. Setelah itu mereka makan tanpa bicara lagi. Sisa puyer masih berada di dalam kotak, dan batuk Danu terdengar dua kali sebelum piring mereka kosong.'] },
      { chapterNumber: 47, title: 'Danu Diam Depan Tungku', paragraphs: ['Vina berbicara sambil menunggui tungku dan Danu menjawab dari kursi belakangnya. Danu meminta Vina tidak membawa urusan air ke kantor. Kartu ia sisipkan di bawah kaleng kerupuk. Api tungku padam sebelum pembicaraan berlanjut. Kaleng kerupuk itu tinggal terisi sepertiga bagian saja. Vina menyalakan kembali api dengan sabut kelapa. Keduanya makan tanpa bersuara.'] },
      { chapterNumber: 48, title: 'Danu Diam Sekali Lagi', paragraphs: ['Vina menyebut persoalan itu sekali lagi dan Danu menjawab sebelum kalimatnya selesai. Menurut Danu, pengurus akan mencoret kontraknya jika keluarga mereka dianggap pembuat keributan. Kartu diselipkan ke bawah piring bersih. Danu menunduk ke piring, dan Vina mematikan lampu dapur setelah selesai makan. Piring bersih itu belum sempat dimasukkan ke rak. Lampu dapur mereka berkedip beberapa kali. Vina mematikannya sebelum masuk kamar.'] },
      { chapterNumber: 49, title: 'Kartu Terselip di Dapur', paragraphs: ['Malam itu Vina memandangi kartu yang sudah berpindah ke banyak tempat di dapur. Ia memutuskan tidak mengangkat persoalan tersebut sama sekali. Danu makan tanpa bertanya apa-apa. Di kamar, Vina memejamkan mata sambil mendengar kartu bergeser ketika nampan dapur dipindahkan. Kartu tersebut berpindah lagi ke bawah nampan malam itu. Danu menyelesaikan makannya lebih cepat daripada biasanya.'] },
      { chapterNumber: 50, title: 'Dapur Sunyi Musim Baru', paragraphs: ['Pada malam pembuka musim tanam, Vina menyebut jatah air ketika Danu mulai makan. Danu mengingatkan bahwa kontraknya rapuh dan meminta Vina menghentikan urusan itu. Kartu itu disembunyikannya di bawah tatakan gelas yang telah retak. Mereka menyelesaikan makan tanpa bersuara. Kartu masuk ke balik alas cangkir yang retak, lalu Danu membawa piringnya ke pancuran.'] },
    ], justification: 'Every scene paraphrases the same kitchen exchange and retreat; only the object hiding the card changes while relationship, stakes, and outcome stay identical.' },
    { chapters: [
      { chapterNumber: 6, title: 'Jam Pasir Ditunjukkan', paragraphs: ['Di rumah jaga, Mbah Ripto memperlihatkan pengukur waktu tua dan menerangkan garis penandanya kepada Vina. Dahulu warga memakai alat tersebut untuk membagi giliran sebelum kantor mengatur jadwal. Butiran halus berpindah seluruhnya ke tabung bawah selama Vina mengamati. Ia meminta izin meminjamnya apabila kelak diperlukan.'] },
      { chapterNumber: 14, title: 'Jam Pasir Dilarang Dipakai', paragraphs: ['Bagas melarang Vina memakai jam pasir Mbah Ripto di rumah jaga. Vina meminta alasan, tetapi hanya mendapat jawaban bahwa aturan kantor sudah cukup. Ia membawa jam itu pulang dan memandang pasirnya di meja. Marahnya tumbuh sebentar, lalu hilang tanpa ia mencatat waktu, bertanya pada warga, atau mencoba cara lain.'] },
      { chapterNumber: 15, title: 'Jam Pasir Masih Dilarang', paragraphs: ['Di rumah jaga, seorang kru memberi tahu Vina bahwa alat pasir warisan Ripto tidak boleh diletakkan dekat gerbang. Vina menanyakan siapa yang membuat aturan tersebut, tetapi kru hanya menunjuk kantor di bawah bukit. Ia membungkus jam itu dengan kain lalu menyimpannya di lemari dapur. Kekecewaan datang sebentar dan lenyap tanpa catatan waktu, saksi, maupun upaya lain.'] },
      { chapterNumber: 16, title: 'Jam Pasir Tetap Di Meja', paragraphs: ['Pagi ketiga, petugas kantor mengambil alat pengukur itu dari tangan Vina sebelum ia sampai ke saluran. Saat ditanya, lelaki itu hanya berkata bahwa buku kantor sudah menentukan giliran. Vina membawa kembali jam pasir ke rumah dan meletakkannya di atas tungku dingin. Kemarahannya surut tanpa ukuran baru, teman baru, atau langkah baru; suasana lama pun berulang.'] },
      { chapterNumber: 32, title: 'Jam Pasir Disimpan Lagi', paragraphs: ['Seminggu kemudian papan kecil di dekat saluran melarang alat pengukur pribadi. Vina menemui Bagas dan mendengar penjelasan lama tentang aturan resmi. Ia menggantung jam pasir pada paku kamar, lalu berjalan keluar tanpa mengajak siapa pun melihatnya. Tidak lahir metode, bukti, atau perasaan baru yang bertahan; pembicaraan itu kembali berhenti di titik lama.'] },
      { chapterNumber: 41, title: 'Jam Pasir Dilarang Gerbang', paragraphs: ['Seorang kru melarang Vina meletakkan jam pasir di dekat gerbang saluran pagi itu. Ia menanyakan dasar larangan tersebut dan hanya mendengar bahwa buku kantor sudah cukup. Vina membawa alat itu pulang, meletakkannya di meja, dan membiarkannya di sana sampai matahari tenggelam.'] },
      { chapterNumber: 42, title: 'Jam Pasir Dilarang Halaman', paragraphs: ['Di pelataran rumah jaga, Vina menaruh jam pasir, tetapi kru yang kemarin berjaga menyuruhnya menyimpan alat itu. Ia bertanya siapa yang membuat aturan itu dan tidak memperoleh nama. Alat tersebut ia bungkus kain lalu simpan di lemari. Halaman buku di sakunya tetap kosong ketika jam pasir masuk ke lemari.'] },
      { chapterNumber: 43, title: 'Jam Pasir Dilarang Pematang', paragraphs: ['Seorang petugas menghentikan Vina saat pengukur waktu itu diletakkan di tepi pematang. Pertanyaannya hanya dibalas dengan rujukan umum kepada buku kantor. Ia membawa alat tersebut pulang dan menaruhnya di atas tungku dingin. Tidak seorang pun berada di pematang ketika ia pulang membawa alat itu, dan halaman catatannya tetap kosong. Seluruh butiran jatuh ke tabung bawah tanpa pernah dihitung.'] },
      { chapterNumber: 44, title: 'Jam Pasir Dilarang Balai', paragraphs: ['Vina membawa jam pasir ke balai dan diminta menyimpannya kembali sebelum rapat dimulai. Petugas menyebut catatan resmi kantor sudah memadai saat Vina meminta petugas menunjukkan dasar larangan. Alat itu ia masukkan ke tas goni. Rapat berlangsung tanpa ia menyebut apa pun tentang waktu. Tas goni tersebut ia letakkan di kolong bangku belakang.'] },
      { chapterNumber: 45, title: 'Jam Pasir Dilarang Kantor', paragraphs: ['Bagas menyatakan pengukur pribadi tidak boleh dipakai di sekitar kantor. Ketika Vina meminta dasar larangan, mandor hanya menunjuk buku yang tersimpan di ruangan belakang. Sesampainya di rumah, Vina menggenggam bingkai kayunya beberapa saat sebelum meletakkannya dekat piring kosong. Buku yang ditunjuk Bagas tetap berada di ruangan belakang dengan pintu tertutup.'] },
      { chapterNumber: 46, title: 'Jam Pasir Dilarang Parit', paragraphs: ['Vina membalik jam pasir di parit bawah, tetapi seorang kru menyuruhnya berhenti sebelum butiran mencapai tabung bawah. Kru menyebut pencatatan kantor sudah memadai; Vina bertanya siapa yang menulis aturan itu dan tidak menerima nama. Ia membalut jam pasir memakai potongan sarung tipis, kemudian menaruhnya dalam lemari dapur. Parit sepi ketika ia pergi, dan kertas di sakunya tetap tanpa angka.'] },
      { chapterNumber: 47, title: 'Jam Pasir Dilarang Lagi', paragraphs: ['Di jalan desa, seorang petugas menghadang Vina lalu melarang pengukur pribadi dibawa ke saluran. Vina meminta petugas menunjukkan aturan tertulisnya. Petugas hanya menyebut buku kantor sebelum berjalan mengikutinya. Alat tersebut pulang bersamanya tanpa pernah dipakai. Petugas itu berjalan mengikutinya sampai belokan berikutnya. Jalan desa siang itu berdebu.'] },
      { chapterNumber: 48, title: 'Jam Pasir Ditaruh Rak', paragraphs: ['Di kamar, Vina menaruh alat pengukur itu pada rak miring dan mengamatinya beberapa saat. Pensil tergeletak di samping rak, tetapi Vina hanya menggeser alas kayu ke kiri. Ia menekan bibir, lalu melepaskan tangan dari bingkai kayu jam pasir. Ia menggeser alas kayu ke sisi kiri agar tabung kaca tersebut tidak meluncur jatuh.'] },
      { chapterNumber: 49, title: 'Jam Pasir Tetap Berdebu', paragraphs: ['Debu menutupi jam pasir di rak dan Vina membersihkannya dengan ujung kain. Ia berpikir untuk memakainya esok pagi lalu mengurungkannya. Sesudah dibersihkan, alat itu kembali ke bekas lingkaran debu pada rak. Kain lap yang ia pakai meninggalkan serat halus pada kacanya.'] },
      { chapterNumber: 50, title: 'Jam Pasir Dilarang Musim', paragraphs: ['Pada pembukaan musim tanam, Vina membawa jam pasir menuju gerbang lagi. Kru berkata buku kantor sudah cukup, tetapi tidak menunjukkan halaman atau pengumuman tertulis. Ia bertanya sekali, menerima jawaban umum, lalu membawa alat itu pulang melewati gerbang yang baru dicat. Di rumah, Vina menaruhnya pada bekas lingkaran debu di rak; seluruh pasir masih berada di tabung atas.'] },
    ], justification: 'The timepiece dispute is restaged with the same rule, question, and fading anger; only the location of the ban moves while tactic, evidence, and consequence never do.' },
    { chapters: [
      { chapterNumber: 6, title: 'Papan Dipasang Dalam', paragraphs: ['Papan daftar jatah air dipindahkan ke dalam ruangan kantor dan tidak lagi ditempel di gerbang. Petugas berkata warga cukup menanyakan isinya kepada loket. Vina melihat perubahan itu ketika mengantar karung benih. Saat lewat, Vina hanya melihat tepi papan melalui jendela sebelum meneruskan langkah ke lumbung.'] },
      { chapterNumber: 14, title: 'Tangga Dipindah ke Jendela', paragraphs: ['Vina memindahkan tangga bambu ke jendela kantor agar dapat melihat papan jatah di dalam. Begitu kakinya mencapai anak tangga kedua, seorang kru menyuruhnya turun. Ia menyeret tangga kembali ke gudang dan tidak mencatat apa yang sempat terlihat. Keinginan mengetahui daftar berhenti pada gerakan memindahkan lalu mengembalikan benda yang sama.'] },
      { chapterNumber: 15, title: 'Tangga Kembali Diseret', paragraphs: ['Esok siang Vina menyeret tangga menuju jendela yang sama dan menaiki dua anak tangga sebelum kru mengusirnya. Ia turun, mengembalikan tangga ke dinding gudang, lalu pulang tanpa angka atau saksi. Tidak ada sudut baru, alasan baru, atau akibat baru yang membedakan percobaan kedua dari hari sebelumnya.'] },
      { chapterNumber: 16, title: 'Anak Tangga Kedua Lagi', paragraphs: ['Vina mengulangi perjalanan pendek itu pada sore berikutnya. Tangga diletakkan di bawah jendela, kakinya berhenti pada anak kedua, dan suara kru membuatnya turun. Ia tidak meminta Bu Ningsih membaca dari tempat lain atau menunggu pergantian penjaga. Tangga kembali ke gudang sementara papan di dalam tetap sama sekali tidak diketahui.'] },
      { chapterNumber: 32, title: 'Tangga Tetap Kembali Gudang', paragraphs: ['Beberapa minggu kemudian Vina kembali menyeret tangga, menaiki dua anaknya, lalu turun ketika kru berteriak dari pintu. Ia mengembalikan bambu ke bekas lumpur yang sama dan pergi. Empat percobaan mempertahankan tempat, batas, penolakan, dan hasil identik; bahkan kebiasaannya tidak menghasilkan cara baru untuk melihat daftar tersebut.'] },
      { chapterNumber: 41, title: 'Tangga Diseret Pagi Kabut', paragraphs: ['Kabut pagi menutupi halaman saat Vina memasang tangga bambu di bawah jendela kantor. Baru dua pijakan dinaiki, teguran kru terdengar dari balik pintu. Ia turun dan menyeret alat itu menuju gudang. Saat ia pergi, papan tetap di balik kaca dan buku kecil dalam sakunya masih kosong.'] },
      { chapterNumber: 42, title: 'Tangga Diseret Sesudah Hujan', paragraphs: ['Tanah becek menelan ujung bambu ketika tangga dipasang Vina dekat jendela. Ia naik dua pijakan, lalu suara dari ruangan menyuruhnya pergi. Alat tersebut diseret menuju tempat penyimpanan semula. Ia pulang sendiri; jendela sudah tertutup sebelum pandangannya mencapai baris pertama. Lumpur pada ujung tangga mengering sebelum petang.'] },
      { chapterNumber: 43, title: 'Tangga Diseret Jam Istirahat', paragraphs: ['Jam istirahat dipilih Vina karena ia mengira kantor sedang kosong. Setelah mencapai pijakan kedua, teriakan dari pintu samping memaksanya turun. Ia membawa tangga kembali ke gudang tanpa sempat melihat daftar. Cekungan bekas bambu makin dalam di halaman ketika pintu samping ditutup di belakang Vina.'] },
      { chapterNumber: 44, title: 'Tangga Diseret Hari Pasar', paragraphs: ['Di tengah ramainya hari pasar, Vina kembali menempatkan tangga dekat kaca kantor. Seorang kru mengusirnya saat kaki baru mencapai pijakan kedua. Bambu itu dibawa menuju gudang sementara para pemikul sayur terus melewati halaman tanpa berhenti. Pikulan sayur terus melintas sementara isi papan tetap tidak diketahui.'] },
      { chapterNumber: 45, title: 'Tangga Diseret Sore Hari', paragraphs: ['Menjelang petang Vina memasang tangga pada posisi lama di sisi kantor. Teguran kru menghentikannya setelah dua pijakan, sehingga alat itu dibawa lagi ke gudang. Ia pulang ketika pintu ruangan sudah dikunci dan papan tetap di balik jendela. Bekas gesekan bambu makin jelas pada dinding penyimpanan ketika langit lembah mulai gelap.'] },
      { chapterNumber: 46, title: 'Tangga Diseret Tanpa Alas', paragraphs: ['Vina menegakkan tangga dengan sandal masih terpasang dan menaiki dua pijakan. Kru mendengar gerakannya lalu memerintahkannya turun. Ia mengangkut tangga menuju gudang lewat jalur yang sama. Debu halaman melekat pada alas kakinya ketika ia pulang, sementara tirai jendela sudah ditarik rapat.'] },
      { chapterNumber: 47, title: 'Tangga Diseret Sekali Lagi', paragraphs: ['Ketika Vina mencapai pijakan kedua, penjaga berteriak dari pintu dan menyuruhnya turun. Ia turun lalu membawa bambu menuju cekungan lama dekat gudang sementara kedua penjaga masih berdiri di pintu. Kedua penjaga telah mengenali wajahnya, tetapi tak seorang pun menanyakan tujuan kedatangannya.'] },
      { chapterNumber: 48, title: 'Tangga Diseret Menjelang Tutup', paragraphs: ['Ketika kantor hampir tutup, Vina menegakkan tangga dan mulai naik menuju jendela. Kru menghalaunya sebelum pandangannya mencapai ruangan. Ia menurunkan alat itu, menyimpannya lagi, kemudian pulang. Kunci pintu diputar dua kali di belakangnya sebelum ia mencapai ujung halaman berdebu dekat pagar.'] },
      { chapterNumber: 49, title: 'Tangga Dibiarkan Gudang', paragraphs: ['Malam itu Vina berniat membiarkan tangga tersimpan pada hari berikutnya, tetapi niat tersebut goyah sebelum tidur. Saat makan malam, Vina tidak menyebut tangga kepada Danu; lampu sekolah Bu Ningsih sudah padam. Bambu tetap bersandar di ruang penyimpanan dengan ujung mulai pecah. Sebelum tidur, pandangannya tetap menuju gudang, tempat ujung bambu yang pecah tampak melalui pintu.'] },
      { chapterNumber: 50, title: 'Tangga Diseret Musim Baru', paragraphs: ['Awal musim tanam membawa Vina kembali ke sisi kantor bersama tangga bambu. Teguran kru menghentikannya pada pijakan kedua, kemudian alat itu dibawa pulang ke gudang. Teguran datang sebelum matanya mencapai baris paling bawah di balik kaca. Cat jendela telah diperbarui; papan di baliknya belum pernah terbaca satu baris pun oleh Vina.'] },
    ], justification: 'The ladder attempt repeats with the same window, second-rung interruption, retreat, and zero information; only hour, weather, and footwear differ across every chapter.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 6, title: 'Papan Jadwal Dipaku', paragraphs: ['Papan jadwal pembagian air dipaku di gerbang saluran menjelang musim tanam. Warga berkerumun membaca jam giliran masing-masing pada pagi pertama. Vina mencari barisan petaknya dan menemukannya di urutan terbawah. Buku musim sebelumnya tetap berada di rumah ketika ia membaca papan tersebut. Paku papan tersebut ditancapkan miring sehingga sudutnya menggantung. Warga membaca sambil berdiri berdesakan.'] },
      { chapterNumber: 14, title: 'Papan Jadwal di Gerbang', paragraphs: ['Vina menunjuk jam yang dipotong pada papan jadwal dan Bagas berkata daftar itu sudah final. Ia pulang sambil menahan kesal, membawa kartu tanpa salinan. Di pematang ia melihat dua penanam lain membaca papan yang sama, tetapi tidak berbicara kepada mereka. Pertemuan pertama itu berakhir dengan kegagalan yang tidak berubah menjadi tindakan.'] },
      { chapterNumber: 15, title: 'Papan Jadwal Dibaca Sendiri', paragraphs: ['Esok pagi Vina membaca papan itu lagi dari sisi parit. Bagas mengulang bahwa daftar sudah ditetapkan. Dengan rahang mengeras, ia menyimpan kartunya di dalam saku. Namun kali ini satu angka dari petak tetangga disalin pada telapak tangannya sebelum hujan turun. Catatan kecil tersebut belum cukup mengajak siapa pun berdiri bersamanya.'] },
      { chapterNumber: 16, title: 'Papan Jadwal Saat Pasar', paragraphs: ['Di dekat pasar, Vina menceritakan satu angka yang disalinnya kepada Bu Ningsih, tetapi guru itu belum melihat papan secara langsung. Mereka sepakat memeriksa lagi lain waktu. Bagas tidak hadir dan tidak ada pertengkaran baru. Vina merasa sedikit kurang sendiri, meski belum memiliki bukti yang dapat mengubah pembagian hari itu.'] },
      { chapterNumber: 32, title: 'Papan Jadwal Masih Sama', paragraphs: ['Ketika jadwal berikutnya dipasang, Vina kembali mendatangi gerbang dengan kartu lama. Bagas memberi jawaban yang serupa, dan ia pulang tanpa menggugat. Bu Ningsih belum sempat ikut. Satu angka yang pernah disalin tetap tersimpan di buku, memberi gema kecil pada percakapan lama tanpa mengubah taktik, tempat utama, atau hasil sengketa.'] },
      { chapterNumber: 41, title: 'Angka Kedua Disalin', paragraphs: ['Satu angka milik petak utara dipindahkan Vina ke buku kecilnya. Saat ia meminta penjelasan, Bagas hanya menyatakan susunan pada papan bersifat final. Dua angka kini berada pada halaman yang sama, dipisahkan garis tipis. Sesudah menutup buku, Vina melewati rumah pemilik petak tetangga tanpa mengetuk pintunya.'] },
      { chapterNumber: 42, title: 'Papan Dibaca Bersama Ningsih', paragraphs: ['Bu Ningsih akhirnya ikut berdiri di depan papan dan membaca dua barisan yang disebut Vina. Guru itu mengangguk lalu berkata angkanya memang berbeda. Keduanya tidak menyalin apa pun hari itu. Dalam perjalanan pulang, Bu Ningsih menyebut kedua angka itu sekali lagi dari ingatan.'] },
      { chapterNumber: 43, title: 'Angka Ketiga Ditemukan', paragraphs: ['Vina menemukan angka ketiga yang berbeda pada barisan petak lereng bawah. Ia menyalinnya di halaman yang sama seperti dua angka sebelumnya. Bagas menjawab pertanyaannya dengan kalimat yang lama. Tiga baris angka kini memenuhi setengah halaman buku kecil itu. Petak lereng bawah tersebut memperoleh giliran paling pagi. Vina membacanya dua kali untuk memastikan.'] },
      { chapterNumber: 44, title: 'Papan Diganti Kertas', paragraphs: ['Papan kayu diganti kertas yang ditempel dengan lem dan lebih mudah sobek. Vina membaca angka-angka lama pada tempelan baru tersebut. Ia menyalin satu barisan lagi ke bukunya. Sudut kertas tempelan tersebut sudah terkelupas pada hari pertama, dan Vina menekannya kembali setelah selesai menyalin.'] },
      { chapterNumber: 45, title: 'Ningsih Menyimpan Salinan', paragraphs: ['Bu Ningsih meminta menyimpan salinan empat angka itu di lemari kelas. Vina menyerahkan halaman yang sudah ia robek rapi dari bukunya. Guru itu memasukkannya ke map tanpa memberi tanda. Satu halaman berada di map kelas, sedangkan salinan kedua tetap terselip dalam buku Vina di rumah.'] },
      { chapterNumber: 46, title: 'Papan Ditutup Terpal', paragraphs: ['Terpal dipasang menutupi papan pada hari hujan dan Vina harus mengangkatnya untuk membaca. Bagas melihat dan berkata daftar sudah final. Ia menurunkan terpal itu lalu pulang. Tetesan air dari terpal membasahi bahu kanannya ketika ia menutup buku dan meninggalkan gerbang.'] },
      { chapterNumber: 47, title: 'Angka Kelima Disalin', paragraphs: ['Vina menyalin angka kelima dari barisan yang paling atas dan menambahkannya ke buku. Ia menarik garis di bawah tiga angka yang berulang, lalu berhenti sebelum menulis keterangan di sampingnya. Bagas tidak hadir di gerbang hari itu. Barisan paling atas itu memuat petak milik keluarga pengurus kebun. Begitu seseorang mendekat, Vina menutup buku dan menyimpannya ke dalam baju.'] },
      { chapterNumber: 48, title: 'Ningsih Menanyakan Kelanjutan', paragraphs: ['Bu Ningsih menanyakan apakah kelima angka itu akan dibawa ke suatu tempat. Vina menjawab belum tahu dan berkata ingin menunggu jumlahnya cukup. Guru itu tidak mendesaknya. Bu Ningsih kembali ke sekolah sambil membawa tumpukan buku tulis, sedangkan Vina meneruskan langkah lewat pematang menuju petaknya sendiri. Mereka berpisah di tikungan dekat rumpun bambu tanpa menentukan waktu untuk bertemu lagi.'] },
      { chapterNumber: 49, title: 'Buku Dibaca Sendiri', paragraphs: ['Vina membaca kelima angka di kamarnya dan mencoba menyusunnya menjadi satu kalimat. Tulisan itu berhenti pada kata kedua. Vina meletakkan pensil di samping buku, menutup sampulnya sekali, lalu menyelipkannya ke bawah bantal sebelum memadamkan lampu. Dari ruang depan terdengar Danu membalik badan di atas tikar, tetapi Vina tidak mengambil kembali buku tersebut.'] },
      { chapterNumber: 50, title: 'Papan Baru Dipaku', paragraphs: ['Papan jadwal musim berikutnya dipaku di gerbang yang sama dan Vina kembali membacanya. Ketika Vina bertanya, Bagas kembali berkata susunan pada papan sudah final. Lima angka lama tetap tertulis pada halaman yang tidak dikeluarkan Vina dari sakunya. Gerbang dibuka menurut urutan pada papan baru yang dipaku memakai kayu lebih tebal. Vina menutup buku berisi lima angka lalu kembali ke petaknya.'] },
    ], justification: 'Copied neighbour numbers and one confidante add modest information each chapter, but the principal confrontation, the board, and the allocation outcome remain substantially unchanged.' },
    { chapters: [
      { chapterNumber: 6, title: 'Simpang Berbatu Putih', paragraphs: ['Simpang jalan menuju kantor pengairan dipenuhi batu kerikil putih yang dibawa dari sungai. Warga memakainya untuk mengeraskan jalan sesudah musim hujan panjang. Vina melewatinya setiap kali mengantar benih ke lumbung. Setiap kali lewat, kedua tangannya tetap memegang keranjang benih dan kerikil hanya berbunyi di bawah gerobak. Kerikil tersebut berbunyi di bawah roda gerobak setiap sore.'] },
      { chapterNumber: 14, title: 'Bel Menjawab dari Dalam', paragraphs: ['Vina menarik tali bel lalu mendengar Bagas berkata berkas pemindahan masih disusun di balik tirai. Ia menunggu sendirian lalu pulang tanpa melihat siapa pun. Di simpang, ia mengambil satu kerikil putih sebagai pengingat lamanya menunggu, tetapi tidak mencatat jam atau menceritakan kunjungan itu kepada keluarga lain.'] },
      { chapterNumber: 15, title: 'Kerikil Kedua di Saku', paragraphs: ['Kunjungan berikutnya mengulang bel, tirai, dan jawaban yang sama. Vina kembali menunggu lalu mengambil kerikil kedua sebelum pulang. Dua benda di sakunya memberi bentuk kecil pada kejengkelan, tetapi belum menunjukkan durasi atau siapa lagi yang mengalami penolakan. Bagas tetap tidak perlu membuka pintu maupun menyebut tanggal keputusan.'] },
      { chapterNumber: 16, title: 'Kerikil Ditunjukkan Laras', paragraphs: ['Laras melihat dua kerikil ketika Vina membayar teh dan bertanya dari mana asalnya. Vina menceritakan beranda kantor dengan suara pelan, lalu Laras berkata ia pernah menunggu di sana juga. Mereka tidak menyamakan jam atau menghubungi orang lain. Pengakuan itu mengurangi kesendirian, tetapi pola kunjungan belum berubah menjadi catatan yang dapat menuntut jawaban.'] },
      { chapterNumber: 32, title: 'Bel dan Tiga Kerikil', paragraphs: ['Saat kembali ke kantor, Vina membunyikan bel dan menerima jawaban lama. Ia mengambil kerikil ketiga, lalu menunjukkan ketiganya kepada Laras setelah pulang. Mereka sepakat kelak membawa kursi bila surat tetap tidak ada. Gema penantian kini mempunyai sekutu dan rencana tipis, namun beranda masih kosong dan keputusan jatah belum bergeser.'] },
      { chapterNumber: 41, title: 'Kerikil Keempat Diambil', paragraphs: ['Vina menarik bel, mendengar jawaban lama, lalu mengambil kerikil keempat di simpang. Ia menyimpannya di saku bersama tiga kerikil sebelumnya. Laras menanyakan jumlahnya ketika ia membayar teh. Buku Laras tetap tertutup di bawah meja ketika keempat batu itu dihitung. Teh yang ia bayar hari itu disajikan tanpa gula. Laras tidak menanyakan lebih jauh.'] },
      { chapterNumber: 42, title: 'Kerikil Dipindah Kaleng', paragraphs: ['Kerikil di saku mulai berat dan Vina memindahkannya ke kaleng bekas teh di rumah. Kaleng tersebut ditempatkannya pada rak dapur agar mudah terlihat. Pagi itu Vina meninggalkan beranda membawa batu keempat setelah Bagas hanya menyebut berkas. Empat batu berbunyi di dalam kaleng yang masih berbau teh melati ketika dibuka.'] },
      { chapterNumber: 43, title: 'Laras Menambah Kerikil', paragraphs: ['Laras memasukkan dua kerikilnya sendiri ke dalam kaleng sesudah menunggu di beranda. Vina menulis nama Laras di samping dua garis baru pada secarik kertas. Sore itu hanya sandal Vina dan Laras yang berada di depan rak tempat kaleng disimpan. Enam batu memenuhi dasar kaleng, sedangkan secarik kertas di sampingnya hanya memuat nama Laras. Kedua kerikil Laras berwarna lebih gelap daripada milik Vina. Warna itu tidak mereka catat.'] },
      { chapterNumber: 44, title: 'Kaleng Dilihat Ningsih', paragraphs: ['Bu Ningsih melihat kaleng itu ketika mengantar buku ke rumah Vina dan menanyakan artinya. Vina menerangkan tentang beranda dan bel yang tidak menghasilkan surat. Guru itu menyarankan menuliskan tanggalnya. Vina mengiyakan, lalu membiarkan buku pemberian Bu Ningsih tergeletak di meja sampai malam.'] },
      { chapterNumber: 45, title: 'Kerikil Ketujuh Dimasukkan', paragraphs: ['Kunjungan berikutnya menghasilkan kerikil ketujuh yang dimasukkan Vina ke dalam kaleng. Vina menarik bel; Bagas menjawab dari belakang kain bahwa petugas masih menata surat. Pensil di meja tetap berada dalam cangkir ketika batu ketujuh dimasukkan. Kaleng tersebut berbunyi lebih berat ketika digoyang. Vina menyimpannya kembali ke rak dapur pada tempat semula. Danu tidak menanyakan isinya.'] },
      { chapterNumber: 46, title: 'Kursi Dibicarakan Lagi', paragraphs: ['Laras berkata kursi warung dapat dibawa bila pintu tetap tertutup pada kunjungan berikutnya. Ketika mereka berpisah, kalender warung tetap tergantung tanpa satu hari pun diberi lingkaran. Hari itu Vina menarik bel, mendengar bahwa surat masih disusun, lalu pulang dari beranda. Kursi kayu tetap berada di gudang warung ketika Laras mengunci pintunya.'] },
      { chapterNumber: 47, title: 'Kerikil Kesembilan Diambil', paragraphs: ['Sesudah menunggu lebih lama, Vina mengambil kerikil kesembilan di simpang kantor. Bagas berbicara dari belakang tirai, menyebut berkas belum selesai, dan membiarkan pintu tertutup. Malamnya batu itu dimasukkan ke kaleng. Laras mengangguk; Vina memasukkan batu pipih itu ke kaleng sementara pensil tetap berada di rak.'] },
      { chapterNumber: 48, title: 'Kaleng Hampir Penuh', paragraphs: ['Kaleng bekas teh itu hampir penuh dan Vina menimbangnya di tangan. Ia memasukkan kaleng ke tas, lalu mengeluarkannya lagi sebelum berangkat ke beranda. Hari berikutnya ia menarik bel, mendengar alasan lama, dan pulang dengan satu kerikil lagi. Berat kaleng kira-kira setara dengan satu takar benih. Vina mengembalikannya ke rak ketika Danu sudah berada di kamar dan jalan depan rumah sepi.'] },
      { chapterNumber: 49, title: 'Kaleng Diletakkan Meja', paragraphs: ['Vina meletakkan kaleng itu di meja dapur dan menghitung isinya bersama Laras sampai larut. Jumlahnya dua belas dan mereka mengingat sebagian tanggalnya. Pensil tetap tergeletak di ujung meja ketika kedua belas batu dimasukkan kembali. Saat mereka selesai menghitung, bangku dan lantai beranda kantor terlihat kosong dari simpang. Lampu dapur mereka padam sekali ketika hitungan hampir selesai.'] },
      { chapterNumber: 50, title: 'Bel Ditarik Membawa Kaleng', paragraphs: ['Pada awal musim berikutnya, kaleng kerikil ikut berada dalam tas Vina ketika ia membunyikan bel kantor. Di belakang kain, suara Bagas menyebut petugas masih mengerjakan surat. Kaleng tetap tertutup di dasar tas selama Vina berdiri di beranda. Dalam perjalanan pulang ia mengambil batu ketiga belas dan memasukkannya ke kaleng yang tidak memuat tanggal.'] },
    ], justification: 'The hidden-office rejection gains pebbles, a tin, one confidante, and a repeatedly deferred chair plan, but yields no present accountability, no written record, and no changed allocation.' },
    { chapters: [
      { chapterNumber: 6, title: 'Rak Bumbu Dipasang', paragraphs: ['Danu memasang rak bumbu dari papan bekas di dinding dapur dekat tungku. Vina menata botol dan kaleng di atasnya menurut urutan pemakaian. Keduanya makan malam dengan dapur yang terasa lebih lapang. Rak baru itu hanya memuat botol lada, garam, gula, dan dua kaleng kosong.'] },
      { chapterNumber: 14, title: 'Dapur Menjadi Sunyi', paragraphs: ['Danu meminta Vina berhenti menanyakan jatah air karena kontraknya rapuh. Ia menyelipkan kartu di bawah alas piring dan membiarkan makan malam sunyi. Vina merasa bersalah karena tidak membela kakaknya, tetapi tidak mengatakannya. Percakapan ini berhenti pada permintaan diam seperti banyak malam sebelumnya.'] },
      { chapterNumber: 15, title: 'Mangkuk Dipindahkan ke Rak', paragraphs: ['Danu meminta hal yang sama ketika Vina membawa kartu ke dapur. Ia menyimpan kartu bukan di bawah mangkuk, melainkan di rak bumbu dekat tungku. Mereka tetap makan tanpa bicara soal kantor. Perpindahan kecil itu membuat Vina tidak perlu melihat kartu setiap kali mengambil nasi, tetapi tidak membuka pembicaraan baru.'] },
      { chapterNumber: 16, title: 'Kartu Ditemukan Bu Ningsih', paragraphs: ['Bu Ningsih mencari garam di rak bumbu dan menemukan kartu yang terselip. Vina menjelaskan pemotongan jatah dengan suara pelan, lalu meminta guru itu tidak menyebutnya kepada Danu. Bu Ningsih mengangguk tanpa janji. Pengakuan singkat itu mengurangi sedikit kesunyian, namun keluarga mereka tetap memilih diam di meja makan.'] },
      { chapterNumber: 32, title: 'Dapur Sunyi Setelah Hujan', paragraphs: ['Saat Danu kembali meminta Vina berhenti bertanya, ia tidak lagi menyembunyikan kartu di bawah mangkuk, tetapi meletakkannya di rak bumbu. Bu Ningsih belum melakukan apa pun dengan cerita itu. Makan malam tetap sunyi dan kontrak Danu tetap rapuh. Gema perubahan tempat kartu tidak mengubah penolakan atau hubungan utama mereka.'] },
      { chapterNumber: 41, title: 'Kartu Naik Rak Atas', paragraphs: ['Danu mengulangi permintaan agar urusan jatah tidak diteruskan karena pekerjaan kebunnya masih rapuh. Vina menaruh kartu pada rak bumbu tertinggi, jauh dari jangkauan ketika memasak. Mereka menghabiskan makan malam tanpa membicarakan kantor lagi. Keesokan pagi kartu masih berada di belakang botol lada ketika Vina menyiapkan air jahe.'] },
      { chapterNumber: 42, title: 'Ningsih Menanyakan Kartu', paragraphs: ['Bu Ningsih menanyakan kabar kartu yang pernah ia temukan di rak bumbu. Vina berkata kartu masih berada di rak dan Danu tetap melarangnya pergi ke kantor, lalu meminta guru itu diam. Bu Ningsih mengangguk tanpa berjanji, lalu meneruskan jalan dari pagar rumah menuju sekolah tanpa menoleh lagi.'] },
      { chapterNumber: 43, title: 'Danu Melihat Rak', paragraphs: ['Danu mengambil garam dan melihat sudut kartu menyembul di rak atas. Ia tidak berkata apa pun dan mendorongnya lebih dalam. Vina memperhatikannya dari depan tungku tanpa bersuara. Makan malam berakhir tanpa pembicaraan mengenai kantor pengairan. Garam yang ia ambil tertinggal di meja sampai pagi. Rak atas tersebut sulit dijangkau Vina.'] },
      { chapterNumber: 44, title: 'Kartu Dimasukkan Kaleng', paragraphs: ['Vina memasukkan kartu ke kaleng bekas biskuit di rak yang sama agar tidak terlihat. Ketika Vina menyebut kantor, Danu meminta kartu itu tetap berada di rumah. Makan malam berakhir ketika Vina menutup kaleng biskuit yang penyok pada satu sisinya di atas kartu tersembunyi. Vina menekannya agar rapat.'] },
      { chapterNumber: 45, title: 'Ningsih Menitipkan Pesan', paragraphs: ['Bu Ningsih menitipkan pesan lewat murid bahwa lemari kelas terbuka bila Vina memerlukannya. Vina membacanya lalu menyimpan kertas itu di kaleng biskuit. Ia tidak mendatangi sekolah pada pekan itu. Pesan Bu Ningsih masuk ke kaleng, dan sepanjang pekan Vina tidak melewati jalan menuju sekolah. Murid pembawa pesan itu menunggu jawaban lalu pulang sendiri.'] },
      { chapterNumber: 46, title: 'Danu Menyebut Mandor', paragraphs: ['Danu berkata, “Bagas dapat mencoret namaku,” lalu menunduk ke meja. Vina membiarkan pertanyaan lanjutannya tertahan. Sesudah menyebut nama itu, Danu kembali meminta Vina tidak membawa kartu keluar rumah. Nama Bagas diucapkan lebih pelan daripada kalimat lain dan hanya dibalas satu anggukan Vina.'] },
      { chapterNumber: 47, title: 'Kaleng Dipindah Lemari', paragraphs: ['Vina memindahkan kaleng biskuit dari rak bumbu ke lemari kamarnya sesudah Danu menyebut nama itu. Saat makan malam, hanya bunyi sendok Danu yang terdengar dari dapur. Lemari di kamar tersebut tidak berkunci dan pintunya sering menganga. Vina mengganjalnya memakai potongan kardus, lalu memeriksa dari pintu bahwa kaleng tidak terlihat sebelum kembali ke meja makan.'] },
      { chapterNumber: 48, title: 'Danu Bertanya Kartu', paragraphs: ['Danu menanyakan tempat kartu jatah disimpan, dan Vina menyebut lemari kamar. Kakaknya mengangguk dan meminta benda tersebut tidak dibawa keluar rumah. Mereka menuntaskan makan tanpa percakapan lanjutan. Sesudah mencuci piring sendiri, ia berbaring di ruang depan. Pintu lemari kamar tetap tertutup hingga lampu dapur dipadamkan.'] },
      { chapterNumber: 49, title: 'Kartu Dibaca Malam', paragraphs: ['Vina mengeluarkan kartu dari lemari dan membaca angka birunya di bawah lampu kamar. Ia memikirkan lemari kelas Bu Ningsih lalu menyimpannya kembali. Danu sudah tidur di ruang depan. Ia melipat kartu, mematikan lampu, dan tetap terjaga ketika Danu berbalik di ruang depan. Angka biru tersebut sudah mulai pudar di bagian sudutnya.'] },
      { chapterNumber: 50, title: 'Dapur Sunyi Rak Baru', paragraphs: ['Pembukaan musim tanam diikuti pemasangan rak bumbu tambahan oleh Danu. Pada malam yang sama Danu berkata, “Biarkan urusan jatah itu,” ketika Vina mulai menyebut kantor. Kartu berada di lemari kamar; Danu masih menyimpan kontrak kebunnya di bawah tikar ruang depan. Mereka makan tanpa bicara di bawah rak baru dari kayu sisa kandang, sementara kartu tetap tersimpan di lemari kamar.'] },
    ], justification: 'Relocating the card and quiet exchanges with Bu Ningsih and Danu create slight emotional variation, but the request, family silence, and stakes remain essentially the same.' },
  ],
}
